 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            minc = min(x for y, x in cells)
            shape = frozenset((y-minr, x-minc) for y, x in cells)
            out.append((color, cells, shape))
    return out


def transform(grid):
    result = [row[:] for row in grid]
    comps = _components(grid)
    colors_by_shape = {}
    for color, cells, shape in comps:
        if color != 1:
            colors_by_shape.setdefault(shape, set()).add(color)
    for color, cells, shape in comps:
        if color == 1:
            matches = colors_by_shape.get(shape, set())
            if len(matches) == 1:
                new_color = next(iter(matches))
                for r, c in cells:
                    result[r][c] = new_color
    return result
